// Des: Async cloud sync: records to the cloud DB, raw pages as packs
// Flo: create cloud tables > send record rows in one batch > pack due raw files into 1 archive per run, upload, write manifest, mark done > any failure leaves rows queued with backoff
// I/O: local Db + raw files + Store + Sql (caller) > cloud rows and runs/<date>.pack objects; Sres counts
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const stor = @import("sy-clou-stor.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const s3v4 = @import("sy-clou-s3v4.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .magi = "SCRAPK1\n", .bodz = 60000, .maxp = 64 << 20, .rawd = "raw" };
pub const Sync = struct { iozz: std.Io, dbzz: *sqli.Dbzz, dirz: []const u8, conf: cfgz.Conf, store: stor.Stor, sql2: sqlz.Sqlz };
pub const Sres = struct { recs: u32 = 0, fil2: u32 = 0, pac2: u64 = 0, fail: u32 = 0, pack: []const u8 = "" };
fn urlh(aren: std.mem.Allocator, urlz: []const u8) ![]const u8 { return aren.dupe(u8, &hash.hashHexz(urlz)); }
fn cutz(text: []const u8) []const u8 { if (text.len <= CF.bodz) return text; var endz: usize = CF.bodz; while (endz > 0 and (text[endz] & 0xC0) == 0x80) endz -= 1; return text[0..endz]; }
fn numz(aren: std.mem.Allocator, valu: i64) ![]const u8 { return std.fmt.allocPrint(aren, "{d}", .{valu}); }
fn reczStmt(self: *Sync, aren: std.mem.Allocator, urlz: []const u8, list: *std.ArrayList([]const u8)) !bool { const row2 = (try inde.pageGetz(self.dbzz, aren, urlz)) orelse return false; const recz = (try inde.recoGetz(self.dbzz, aren, urlz)) orelse return false; const dial = self.sql2.dial; const uhzz = try sqlz.litz(aren, dial, try urlh(aren, urlz)); const page = [_]sqlz.Colz{ .{ .name = "urlh", .valu = uhzz }, .{ .name = "urlz", .valu = try sqlz.litz(aren, dial, urlz) }, .{ .name = "hexz", .valu = try sqlz.litz(aren, dial, row2.hexz) }, .{ .name = "code", .valu = try numz(aren, row2.code) }, .{ .name = "tier", .valu = try numz(aren, row2.tier) }, .{ .name = "vend", .valu = try sqlz.litz(aren, dial, row2.vend) }, .{ .name = "fetc", .valu = try numz(aren, row2.fetc) } }; const reco = [_]sqlz.Colz{ .{ .name = "urlh", .valu = uhzz }, .{ .name = "hexz", .valu = try sqlz.litz(aren, dial, recz.hexz) }, .{ .name = "kind", .valu = try sqlz.litz(aren, dial, recz.kind) }, .{ .name = "body", .valu = try sqlz.litz(aren, dial, cutz(recz.body)) }, .{ .name = "timz", .valu = try numz(aren, row2.fetc) } }; try list.append(aren, try sqlz.upse(aren, dial, "cl_page", "urlh", &page)); try list.append(aren, try sqlz.upse(aren, dial, "cl_reco", "urlh", &reco)); return true; }
fn syncRecs(self: *Sync, aren: std.mem.Allocator, nowz: i64, rslt: *Sres) !void { const duez = try outb.outbDuez(self.dbzz, aren, "rec", nowz, self.conf.clou_sync_batz); if (duez.len == 0) return; var stmz: std.ArrayList([]const u8) = .empty; var good: std.ArrayList([]const u8) = .empty; for (duez) |item| { if (try reczStmt(self, aren, item.keyz, &stmz)) try good.append(aren, item.keyz) else try outb.outbDone(self.dbzz, "rec", item.keyz); } if (stmz.items.len == 0) return; self.sql2.exec(self.sql2.ctx2, aren, self.iozz, stmz.items) catch |err3| { for (good.items) |urlz| try outb.outbFail(self.dbzz, "rec", urlz, @errorName(err3), nowz); rslt.fail += @intCast(good.items.len); return err3; }; for (good.items) |urlz| try outb.outbDone(self.dbzz, "rec", urlz); rslt.recs += @intCast(good.items.len); }
fn syncFile(self: *Sync, aren: std.mem.Allocator, nowz: i64, rslt: *Sres) !void { const duez = try outb.outbDuez(self.dbzz, aren, "file", nowz, self.conf.clou_sync_batz); if (duez.len == 0) return; var pac2: std.ArrayList(u8) = .empty; try pac2.appendSlice(aren, CF.magi); const Entr = struct { hexz: []const u8, offs: u64, lenz: u64 }; var ents: std.ArrayList(Entr) = .empty; const rawd = try std.fs.path.join(aren, &.{ self.dirz, CF.rawd }); for (duez) |item| { if (!hash.hashOkay(item.keyz)) { try outb.outbFail(self.dbzz, "file", item.keyz, "bad hash", nowz); continue; } var buff: [96]u8 = undefined; const rela = try hash.hashPath(&buff, item.keyz[0..64].*); const path = try std.fs.path.join(aren, &.{ rawd, rela }); const gzzz = std.Io.Dir.cwd().readFileAlloc(self.iozz, path, aren, .limited(CF.maxp)) catch { try outb.outbFail(self.dbzz, "file", item.keyz, "local file missing", nowz); rslt.fail += 1; continue; }; if (pac2.items.len + gzzz.len > CF.maxp) break; try pac2.appendSlice(aren, item.keyz); var lenb: [4]u8 = undefined; std.mem.writeInt(u32, &lenb, @intCast(gzzz.len), .little); try pac2.appendSlice(aren, &lenb); try ents.append(aren, .{ .hexz = item.keyz, .offs = pac2.items.len, .lenz = gzzz.len }); try pac2.appendSlice(aren, gzzz); } if (ents.items.len == 0) return; var dbuf: [16]u8 = undefined; const key2 = try std.fmt.allocPrint(aren, "runs/{s}-{x}.pack", .{ s3v4.dateNowz(&dbuf, nowz), std.hash.Wyhash.hash(0, pac2.items) & 0xffff }); self.store.put(self.store.ctx2, aren, self.iozz, key2, pac2.items) catch |err3| { for (ents.items) |entr| try outb.outbFail(self.dbzz, "file", entr.hexz, @errorName(err3), nowz); rslt.fail += @intCast(ents.items.len); return err3; };
var stmz: std.ArrayList([]const u8) = .empty; for (ents.items) |entr| { const cols = [_]sqlz.Colz{ .{ .name = "hexz", .valu = try sqlz.litz(aren, self.sql2.dial, entr.hexz) }, .{ .name = "pack", .valu = try sqlz.litz(aren, self.sql2.dial, key2) }, .{ .name = "offs", .valu = try numz(aren, @intCast(entr.offs)) }, .{ .name = "lenz", .valu = try numz(aren, @intCast(entr.lenz)) } }; try stmz.append(aren, try sqlz.upse(aren, self.sql2.dial, "cl_manif", "hexz", &cols)); } self.sql2.exec(self.sql2.ctx2, aren, self.iozz, stmz.items) catch |err3| { for (ents.items) |entr| try outb.outbFail(self.dbzz, "file", entr.hexz, @errorName(err3), nowz); rslt.fail += @intCast(ents.items.len); return err3; };
try self.dbzz.exec("BEGIN IMMEDIATE;"); errdefer self.dbzz.exec("ROLLBACK;") catch {}; for (ents.items) |entr| { var insz = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz) VALUES(?1,?2,?3,?4) ON CONFLICT(hexz) DO UPDATE SET packk=?2,offs=?3,lenz=?4;"); defer insz.fini(); try insz.bindText(1, entr.hexz); try insz.bindText(2, key2); try insz.bindIntz(3, @intCast(entr.offs)); try insz.bindIntz(4, @intCast(entr.lenz)); _ = try insz.step(); try outb.outbDone(self.dbzz, "file", entr.hexz); } try self.dbzz.exec("COMMIT;"); rslt.fil2 += @intCast(ents.items.len); rslt.pac2 += pac2.items.len; rslt.pack = key2; }
pub fn syncRunz(self: *Sync, aren: std.mem.Allocator, nowz: i64) !Sres { var rslt: Sres = .{}; self.sql2.exec(self.sql2.ctx2, aren, self.iozz, &sqlz.DDL) catch |err3| { rslt.fail += 1; return err3; }; try syncRecs(self, aren, nowz, &rslt); try syncFile(self, aren, nowz, &rslt); return rslt; }
pub fn res3(self: *Sync, aren: std.mem.Allocator, hexz: hash.Hexz) ![]u8 { var stmt = try self.dbzz.prep("SELECT packk,offs,lenz FROM pack WHERE hexz=?1;"); defer stmt.fini(); try stmt.bindText(1, &hexz); if (!try stmt.step()) return error.NotFound; const key2 = try aren.dupe(u8, stmt.colzText(0)); const offs: usize = @intCast(stmt.colzIntz(1)); const lenz: usize = @intCast(stmt.colzIntz(2)); const pac2 = try self.store.get(self.store.ctx2, aren, self.iozz, key2); if (offs + lenz > pac2.len) return error.HashMismatch; const body = try file.gzipOpen(aren, pac2[offs .. offs + lenz], CF.maxp); const back = hash.hashHexz(body); if (!std.mem.eql(u8, &back, &hexz)) return error.HashMismatch; return body; }
